/// <reference types="vite/client" />
import "./guide-style.css";
import { parsePaste, renderCharacter, renderGuide, type GuideOut } from "./guide-view";

// guide.json is generated by `pnpm guide ideal`; falls back to the sample fixture.
const real = Object.values(import.meta.glob("./data/guide.json", { eager: true, import: "default" }))[0] as GuideOut | undefined;
const sample = Object.values(import.meta.glob("./data/guide.sample.json", { eager: true, import: "default" }))[0] as GuideOut;
document.getElementById("ideal")!.innerHTML =
  (real ? "" : `<p class="gl-banner">sample data: run <code>pnpm guide ideal</code> to generate the real guide</p>`) + renderGuide(real ?? sample);

// the player's own character: what the poorchlight button copied, kept in this browser only
const KEY = "tli-lens:paste";
const box = document.getElementById("paste-text") as HTMLTextAreaElement, out = document.getElementById("mine-out")!;
function show(text: string): void {
  if (!text.trim()) { out.innerHTML = ""; return; }
  try {
    const p = parsePaste(text);
    out.innerHTML = p.kind === "advice" ? renderGuide(p.guide)
      : renderCharacter(p.character) + `<p class="gl-banner">This is the raw export: it shows your gear, not what to change. Recommendations come from the guide engine, which runs on your PC
        (it needs dps-debug): the poorchlight button runs it and copies the result, or run <code>pnpm guide advise &lt;export.json&gt;</code> in tli-lens. Paste that result here.</p>`;
    localStorage.setItem(KEY, text);
    document.getElementById("paste")!.removeAttribute("open");
  } catch (e) { out.innerHTML = `<p class="warn"></p>`; out.firstElementChild!.textContent = (e as Error).message; }
}
document.getElementById("paste-go")!.addEventListener("click", () => show(box.value));
document.getElementById("paste-clear")!.addEventListener("click", () => { localStorage.removeItem(KEY); box.value = ""; out.innerHTML = ""; document.getElementById("paste")!.setAttribute("open", ""); });
const kept = localStorage.getItem(KEY);
if (kept) { box.value = kept; show(kept); }
